def spec(code, description, actor, trigger, pre, success, minimum, fields, flow,
         alternatives, errors, rules, access, effects, sources, scenarios):
    return dict(code=code, description=description, actor=actor, trigger=trigger,
                pre=pre, success=success, minimum=minimum, fields=fields, flow=flow,
                alternatives=alternatives, errors=errors, rules=rules, access=access,
                effects=effects, sources=sources, scenarios=scenarios)

